(()=>{const input=document.getElementById('faculty-query');if(!input)return;const rows=[...document.querySelectorAll('.hod-leadership-list>div')],count=document.getElementById('faculty-count'),empty=document.getElementById('faculty-empty');const normalize=text=>text.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();const update=()=>{const words=normalize(input.value).split(' ').filter(Boolean);let visible=0;rows.forEach(row=>{row.hidden=!words.every(word=>normalize(row.textContent).includes(word));if(!row.hidden)visible++});count.textContent=visible+' of '+rows.length+' department heads';empty.hidden=visible!==0};input.addEventListener('input',update);document.getElementById('faculty-reset').addEventListener('click',()=>{input.value='';update();input.focus()});update()})();
